class Node<T> {
    T value; Node<T> prev, next;
    Node(T value) { this.value = value; }
}

class MyLinkedList<T> {
    Node<T> head, tail;

    void add(T value) {
        Node<T> node = new Node<>(value);
        if (head == null) { head = tail = node; }
        else { tail.next = node; node.prev = tail; tail = node; }
    }

    class MyListIterator {
        Node<T> cursor = null;
        Node<T> nextNode = head;

        boolean hasNext() { return nextNode != null; }
        T next() { cursor = nextNode; nextNode = nextNode.next; return cursor.value; }
        boolean hasPrevious() { return cursor != null; }
        T previous() { T v = cursor.value; nextNode = cursor; cursor = cursor.prev; return v; }
    }

    MyListIterator iterator() { return new MyListIterator(); }
}

