class FibonacciIterator implements Iterator<Long> {
    private long a = 0, b = 1;

    public boolean hasNext() { return true; } // nieskonczony

    public Long next() {
        long result = a;
        long next = a + b;
        a = b; b = next;
        return result;
    }
}

