class PeekableIterator<T> implements Iterator<T> {
    private Iterator<T> source;
    private T peeked;
    private boolean hasPeeked = false;

    PeekableIterator(Iterator<T> source) { this.source = source; }

    public boolean hasNext() { return hasPeeked || source.hasNext(); }

    public T next() {
        if (hasPeeked) { hasPeeked = false; return peeked; }
        return source.next();
    }

    T peek() {
        if (!hasPeeked) { peeked = source.next(); hasPeeked = true; }
        return peeked;
    }
}

