class ZipIterator<A, B> implements Iterator<Object[]> {
    private Iterator<A> iterA;
    private Iterator<B> iterB;

    ZipIterator(Iterator<A> iterA, Iterator<B> iterB) {
        this.iterA = iterA; this.iterB = iterB;
    }

    public boolean hasNext() { return iterA.hasNext() && iterB.hasNext(); }

    public Object[] next() { return new Object[]{iterA.next(), iterB.next()}; }
}

