class CachingIterator<T> implements Iterator<T> {
    private Iterator<T> source;
    private int cacheSize;
    private ArrayList<T> cache = new ArrayList<>();

    CachingIterator(Iterator<T> source, int cacheSize) {
        this.source = source; this.cacheSize = cacheSize;
    }

    public boolean hasNext() { return source.hasNext(); }

    public T next() {
        T value = source.next();
        cache.add(value);
        if (cache.size() > cacheSize) cache.remove(0);
        return value;
    }

    List<T> getCache() { return new ArrayList<>(cache); }
}

