class FlatMappingIterator<T> implements Iterator<T> {
    private Iterator<Iterable<T>> outer;
    private Iterator<T> inner = java.util.Collections.emptyIterator();

    FlatMappingIterator(Iterator<Iterable<T>> outer) { this.outer = outer; }

    public boolean hasNext() {
        while (!inner.hasNext() && outer.hasNext()) {
            inner = outer.next().iterator();
        }
        return inner.hasNext();
    }

    public T next() {
        if (!hasNext()) throw new java.util.NoSuchElementException();
        return inner.next();
    }
}

